import win32com.client


# =========================================================
# COMMON WINDOWS APPLICATIONS
# =========================================================

APP_ALIASES = {

    # =====================================================
    # GOOGLE CHROME
    # =====================================================

    "chrome": {
        "command": "chrome.exe",
    },

    "google chrome": {
        "command": "chrome.exe",
