                    f"Could not find application: "
                    f"{app_name}."
                ),
            }

        command_parts = [
            command
        ]

        if arguments:
            command_parts.extend(
                arguments.strip().split()
            )

        subprocess.Popen(
            command_parts,
            shell=False,
        )

        return {
            "success": True,
            "application": app_name,
            "command": command,
            "process": process_name,
            "message": (
                f"Opened {app_name}."
