                normalized
            )
        )

        if automatic_result:

            return (
                automatic_result,
                os.path.basename(
                    automatic_result
                ),
            )

        return None, None

    # =====================================================
    # UNKNOWN APPLICATION
    # =====================================================

    executable = normalized

    if not executable.endswith(
        ".exe"
    ):
        executable += ".exe"

    # -----------------------------------------------------
