            try:

                name = process.info[
                    "name"
                ]

                if not name:
                    continue

                lower_name = (
                    name.lower()
                )

                if (
                    lower_name
                    in system_processes
                ):
                    continue

                if (
                    lower_name
                    in seen
                ):
