        # CLOSE EXACT MATCHED PIDS
        # -------------------------------------------------

        for item in matching_processes:

            pid = item.get(
                "pid"
            )

            if not pid:
                continue

            try:

                process = psutil.Process(
                    pid
                )

                process.terminate()

                closed.append(
                    {
                        "pid": pid,
                        "name": item.get(
                            "name"
                        ),
                    }
                )

