            ) as e:

                failed.append(
                    {
                        "pid": pid,
                        "name": item.get(
                            "name"
                        ),
                        "error": str(e),
                    }
                )

            except Exception as e:

                failed.append(
                    {
                        "pid": pid,
                        "name": item.get(
                            "name"
                        ),
                        "error": str(e),
                    }
                )

        # -------------------------------------------------
        # RESULT
        # -------------------------------------------------

        if not closed and not failed:

            return {
                "success": False,
                "running": False,
                "application": app_name,
                "message": (
                    f"{app_name} is no longer running."
                ),
            }

        return {
            "success": len(failed) == 0,
            "application": app_name,
            "closed_processes": closed,
            "failed": failed,
            "message": (
                f"Closed {app_name}."
                if not failed
                else (
